"""Misc helpers."""


def chunk_list(items, size):
    return [items[i:i + size] for i in range(0, len(items), size)]


def merge_dicts(*dicts):
    result = {}
    for d in dicts:
        result.update(d)
    return result


def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
